insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'lote_4_v1'
from (values
('114.39.c.1.A',1,'In a first-year language class, a partner asks you what you do after school. This is a question about:','["everyday life", "tax forms", "ancient law", "quantum physics"]'::jsonb,0,'Level I students talk about familiar, everyday topics.','original'),
('114.39.c.1.A',2,'Which pair of tasks shows two-way communication at Level I?','["memorizing a poem alone", "asking a question and giving an answer", "reading silently and not responding", "copying a list of words"]'::jsonb,1,'Interpersonal communication goes both ways.','original'),
('114.39.c.1.B',2,'Which sentence frame fits sharing a personal preference in a new language?','["The formula for area is ___.", "The sum of the angles is ___.", "I like ___ because it is fun.", "The treaty was signed in ___."]'::jsonb,2,'Preferences are expressed with simple frames.','original'),
('114.39.c.1.B',2,'Two classmates trade opinions about school lunch in the target language. This exchange is:','["silent copying", "presentational reading only", "a written test only", "interpersonal communication"]'::jsonb,3,'Exchanging opinions is two-way communication.','original'),
('114.39.c.1.C',2,'Which statement tells someone what they must do?','["You must wear a helmet.", "It is sunny.", "The bike is red.", "I like bicycles."]'::jsonb,0,'Must expresses necessity.','original'),
('114.39.c.1.C',2,'At Level I, a student tells a friend what he should do before a test. This uses language of:','["number facts", "advice and obligation", "historical dates", "weather reports"]'::jsonb,1,'Should and must express advice and obligation.','original'),
('114.39.c.1.D',2,'Which sentence makes a polite request?','["Books are made of paper.", "I read yesterday.", "Could you pass me the book, please?", "The book is heavy."]'::jsonb,2,'Requests use polite forms.','original'),
('114.39.c.1.D',3,'A student says, We could go to the park or to the library. This offers:','["a refusal", "a command", "a story", "alternatives"]'::jsonb,3,'Alternatives give options.','original'),
('114.39.c.1.E',2,'In many languages a speaker uses a formal way of addressing a teacher. This is an example of choosing the right:','["register", "alphabet", "map scale", "spelling"]'::jsonb,0,'Register fits the audience and setting.','original'),
('114.39.c.1.E',3,'A culturally appropriate gesture when greeting varies by culture. A learner should:','["use a gesture from a random culture", "observe and use the gestures that fit the culture", "ignore all gestures", "use only the learner''s own gestures"]'::jsonb,1,'Gestures are part of culturally appropriate speech.','original'),
('114.39.c.1.F',2,'A pen pal writes a note to a teacher in the target language. The student should choose:','["slang words", "random letters", "a polite and respectful style", "insults"]'::jsonb,2,'Written style also depends on the reader.','original'),
('114.39.c.1.F',3,'Which written greeting best fits a note to a younger cousin?','["a legal heading", "a technical title", "a formal title and signature block", "a friendly and informal opening"]'::jsonb,3,'Informal writing suits family.','original'),
('114.39.c.2.A',2,'A learner reads a menu from a restaurant in another country. This is an example of using:','["authentic print material", "a blank page", "a cartoon without words", "a made-up worksheet"]'::jsonb,0,'Authentic materials are made by speakers for real use.','original'),
('114.39.c.2.A',3,'Which source counts as authentic audiovisual material?','["a spelling list", "a short video made for native speakers", "a silent drawing", "a classroom rule chart"]'::jsonb,1,'Authentic materials come from real communication.','original'),
('114.39.c.2.B',2,'After watching a short clip, a student lists key words and details. This shows skill in:','["spelling aloud", "presentational writing", "interpretive listening and viewing", "map reading"]'::jsonb,2,'Interpretive skills understand what others produce.','original'),
('114.39.c.2.B',2,'Which detail would a novice learner pick from a short story?','["a philosophical theory", "the author''s hidden agenda", "a tax statement", "the name of a character and where the story happens"]'::jsonb,3,'Key details are concrete and basic.','original'),
('114.39.c.2.C',3,'A learner meets an unfamiliar word in a text with pictures. The best strategy is to:','["use pictures and nearby words to infer meaning", "stop reading", "skip the whole text", "guess a random meaning"]'::jsonb,0,'Context helps in highly contextualized materials.','original'),
('114.39.c.2.C',3,'Highly contextualized material is easier to understand because:','["there is no text", "visual and situational clues support the words", "it avoids pictures", "it has only numbers"]'::jsonb,1,'Context clues support comprehension.','original'),
('114.39.c.2.D',2,'A learner sees a photo of a family meal in a video from another country. What does the learner identify?','["a chemical symbol", "a map legend", "a cultural practice", "a math formula"]'::jsonb,2,'Practices are customs seen in everyday life.','original'),
('114.39.c.2.D',3,'Watching a festival video helps a learner notice:','["the cost of the video", "only the language alphabet", "nothing at all", "customs and traditions of the culture"]'::jsonb,3,'Authentic media show cultural practices.','original'),
('114.39.c.3.A',2,'A student says, I prefer tea, and explains with one reason. This is:','["stating and supporting a preference", "reciting numbers", "asking directions", "describing weather"]'::jsonb,0,'Preferences include simple support.','original'),
('114.39.c.3.A',3,'Which written sentence states and supports an opinion at Level I?','["The ball.", "I like soccer because it is exciting.", "Soccer game ball field.", "Soccer."]'::jsonb,1,'A because clause gives support.','original'),
('114.39.c.3.B',2,'Describing a friend with words and short phrases is an example of:','["tax filing", "interpersonal chatting only", "presentational speaking or writing", "silent viewing"]'::jsonb,2,'Presentational communication is one-way.','original'),
('114.39.c.3.B',3,'At the novice level, a description may use a mixture of:','["only symbols", "only single sounds", "only long paragraphs", "words, phrases and simple sentences"]'::jsonb,3,'Novice learners combine words and phrases.','original'),
('114.40.c.1.A',2,'In Level II a student not only answers a question but adds a detail. This is:','["simple elaboration", "silence", "avoidance", "copying"]'::jsonb,0,'Elaboration adds information.','original'),
('114.40.c.1.A',3,'Which response shows simple elaboration to the question, What did you do on the weekend?','["Yes.", "I went to the lake and swam with my cousins.", "Lake.", "No answer."]'::jsonb,1,'Elaboration gives detail.','original'),
('114.40.c.1.B',3,'At Level II, a student gives an opinion about a movie and adds supporting statements. This builds:','["silent viewing", "only rote spelling", "conversational depth", "only vocabulary lists"]'::jsonb,2,'Supporting statements deepen conversation.','original'),
('114.40.c.1.B',3,'Which pair of statements expresses an opinion with support?','["Yes. Film. Maybe.", "Movie, movie.", "The film.", "I like the film. The music is exciting."]'::jsonb,3,'Support follows the opinion.','original'),
('114.40.c.1.C',3,'A student says, You should sleep early because the test is tomorrow. This tells someone what to do with:','["a supporting reason", "a weather report", "a greeting only", "a request for money"]'::jsonb,0,'Reasons support advice.','original'),
('114.40.c.1.C',3,'Which sentence uses necessity with a reason?','["Guests.", "We must clean the room because guests are coming.", "The room.", "We clean."]'::jsonb,1,'Must plus because gives obligation and reason.','original'),
('114.40.c.1.D',3,'Planning a class party includes making requests, offering alternatives and giving:','["unrelated stories", "random facts", "simple supporting statements", "only numbers"]'::jsonb,2,'Plans are supported by short statements.','original'),
('114.40.c.1.D',3,'A student suggests, We could meet at noon or at one o''clock; noon is better because it is cooler. This offers:','["a refusal only", "a joke", "a command only", "alternatives with a reason"]'::jsonb,3,'The speaker gives options and a reason.','original'),
('114.40.c.1.E',3,'Interacting and reacting in conversation means the student:','["responds to what the other person says", "writes only", "recites memorized lines only", "reads silently"]'::jsonb,0,'Reaction builds real conversation.','original'),
('114.40.c.1.E',3,'A culturally appropriate reaction to good news includes:','["staring silently", "an expression that shows appropriate enthusiasm", "changing the subject", "leaving abruptly"]'::jsonb,1,'Reactions follow cultural norms.','original'),
('114.40.c.1.F',3,'Reacting in writing to a friend''s email by answering questions and adding comments shows:','["only listening", "only copying", "interactive written communication", "only drawing"]'::jsonb,2,'Written interaction responds to messages.','original'),
('114.40.c.1.F',3,'Which closing is culturally appropriate in a note to a teacher?','["no closing and no name", "a rude remark", "a joke only", "a respectful closing with thanks"]'::jsonb,3,'Style fits the reader.','original'),
('114.40.c.2.A',3,'Authentic materials at Level II include:','["a news clip or a short article made for native speakers", "a blank map", "a scrambled alphabet", "a worksheet written only for learners"]'::jsonb,0,'Authentic items are real communication.','original'),
('114.40.c.2.A',3,'A learner watches an audiovisual advertisement from another country. This helps the learner:','["avoid the target language", "see how language and culture work together", "ignore the images", "skip the culture"]'::jsonb,1,'Media connect language and culture.','original'),
('114.40.c.2.B',3,'A theme is:','["the author''s address", "the title page", "the central message of a text", "a single word"]'::jsonb,2,'Themes are central ideas.','original'),
('114.40.c.2.B',3,'Which task shows identifying the main idea and supporting details?','["skipping the story", "counting words", "copying the first sentence", "stating what a story is mostly about and naming two events"]'::jsonb,3,'Main ideas and details show comprehension.','original'),
('114.40.c.2.C',3,'To infer the meaning of an unfamiliar phrase in a highly contextualized video, a learner can:','["use images, gestures and context", "guess at random", "stop watching", "ignore the video"]'::jsonb,0,'Context supports inference.','original'),
('114.40.c.2.C',3,'Inference means:','["copying words", "using clues to figure out what is not directly stated", "ignoring clues", "memorizing a definition"]'::jsonb,1,'Inference is based on clues.','original'),
('114.40.c.2.D',3,'From a short documentary, a learner identifies a family tradition. This shows ability to:','["identify tax codes", "identify chemical formulas", "identify cultural practices", "identify geologic layers"]'::jsonb,2,'Practices are visible in authentic media.','original'),
('114.40.c.2.D',3,'Which feature of a video can reveal a cultural practice?','["the length of the credits", "the brand of the camera", "the file size", "how people greet and eat together"]'::jsonb,3,'Daily routines reveal practices.','original'),
('114.40.c.3.A',3,'At Level II, a student gives an opinion in a short speech and adds supporting statements. This is:','["presentational communication", "silent reading only", "dictionary work", "two-way chatting only"]'::jsonb,0,'Presentations are one-way.','original'),
('114.40.c.3.A',3,'Which written paragraph expresses an opinion with support?','["I ski.", "I prefer winter because I can ski, and the snow is beautiful.", "Snow.", "Winter."]'::jsonb,1,'Support follows the opinion.','original'),
('114.40.c.3.B',3,'Describing a place with a series of sequenced sentences means:','["avoiding detail", "listing random words", "putting details in a logical order", "reading backward"]'::jsonb,2,'Sequence organizes a description.','original'),
('114.40.c.3.B',3,'Which description is organized in sequence?','["Ate and home first.", "Walked home we then arrived.", "Home.", "First we arrived, then we ate, and finally we walked home."]'::jsonb,3,'Sequence words order events.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Languages Other Than English' and d.language = 'en'
on conflict (fingerprint) do nothing;
